#!/usr/bin/env bash
# Patch 89 voor hrmforce-site: Nederlandse tekst uit het Duits, Frans, Spaans
# en Roemeens.
#
#   bash toepassen-89.sh
#
# De logoslider stond op de Duitse homepage in het Nederlands: "Vertrouwd door
# 1.200+ organisaties". Daaronder zat een oorzaak die vier talen tegelijk raakt.
#
# 1. vulAan vulde alleen de talen buiten de brontalen. Een blok met alleen nl en
#    en gaf in de,fr,es,ro dus de Nederlandse tekst, want het paginasjabloon
#    valt terug op nl. Dat gold voor de logoslider (212 pagina's per taal) en
#    voor de bijschriften bij de datavisuals. vulAan vult nu elke taal aan die
#    nog niet in het blok staat, ook een brontaal. Handgeschreven tekst gaat
#    voor, en slugs blijven uitgezonderd, want een slug erbij zou een pagina
#    onder een nieuw adres zetten.
# 2. Een taal die als clone(nl) begint en daarna veld voor veld wordt
#    overschreven, houdt Nederlands in alles wat niet is overschreven. Dat was
#    de hele prijstabel op /tarieven in vier talen: 37 vragenlijsten,
#    Kandidatenbeheer, Basic inrichting, Kickoff. Nieuw hulpje vulRest haalt die
#    vertalingen alsnog op; dit script draait de vertaalronde ervoor.
# 3. DeepL gaf HTML-entiteiten terug, en Astro escapet die nog een keer. Op de
#    Franse homepage stond letterlijk "l&#x27;enseignement". Het script zet ze
#    nu terug en de 309 bestaande gevallen zijn hersteld.
# 4. scripts/taalcontrole.py heeft er een achtste controle bij: tekst die
#    Nederlands bleef terwijl er een vertaling voor bestaat. Die kijkt naar alle
#    brontalen tegelijk en had dit gevonden.
#
# Daarvoor moet DEEPL_API_KEY in de omgeving staan; het gaat om ongeveer 5.400
# tekens per taal voor vier talen.
set -euo pipefail
cd "$(dirname "$0")"
[ -d src/i18n ] || { echo "Draai dit vanuit de hoofdmap van hrmforce-site."; exit 1; }

cat > /tmp/89.b64 <<'B64EOF'
