base64 -d /tmp/89.b64 > /tmp/89.patch
if grep -q "vulRest" src/data/vertaal-inhoud.js; then
  echo "De patch stond er al in, alleen het vertalen en vastleggen nog."
else
  git apply --unidiff-zero /tmp/89.patch
fi
rm -f /tmp/89.b64 /tmp/89.patch

echo
if [ -z "${DEEPL_API_KEY:-}" ]; then
  echo "DEEPL_API_KEY staat niet in de omgeving."
  echo "De patch staat in de bestanden, de prijstabel is nog niet vertaald en"
  echo "er is niets vastgelegd. Zet de sleutel en draai dit script opnieuw:"
  echo
  echo "  export DEEPL_API_KEY=..."
  echo "  bash toepassen-89.sh"
  exit 1
fi

echo "Vertalen van de prijstabel voor Duits, Frans, Spaans en Roemeens..."
HSF_ONLY=tarieven-content.js node scripts/hsf-translate-content.mjs de fr es ro

echo "Mailteksten opnieuw wegschrijven..."
node scripts/genereer-mailteksten.mjs

git add -A
git commit -q -F - <<'MSGEOF'
Nederlandse tekst uit het Duits, Frans, Spaans en Roemeens

De logoslider stond op de Duitse homepage in het Nederlands. Daaronder zat een
oorzaak die vier talen tegelijk raakt.

1. vulAan vulde alleen de talen buiten de brontalen aan. Een blok met alleen nl
   en en gaf in de, fr, es en ro dus de Nederlandse tekst, want het
   paginasjabloon valt terug op nl. Dat gold voor de logoslider, 212 pagina's
   per taal, en voor de bijschriften bij de datavisuals. vulAan vult nu elke
   taal aan die nog niet in het blok staat, ook een brontaal. Een brontaal die
   wel in het blok staat blijft met rust, want handgeschreven tekst gaat voor.
   Slugs blijven uitgezonderd: een slug erbij zet een pagina onder een nieuw
   adres, en dat mag een vertaalronde niet doen.
2. Een taal die als clone van het Nederlands begint en daarna veld voor veld
   wordt overschreven, houdt Nederlands in alles wat niet is overschreven. Dat
   was de hele prijstabel op tarieven in vier talen. Het nieuwe hulpje vulRest
   loopt zo'n blok langs en vervangt elke tekst die nog letterlijk gelijk is aan
   de Nederlandse, mits er een vertaling voor bestaat.
3. DeepL gaf HTML-entiteiten terug en Astro escapet die nog een keer, waardoor
   op de Franse homepage letterlijk l&#x27;enseignement stond. Het vertaalscript
   zet ze nu terug en de 309 bestaande gevallen in de acht vertaalbestanden zijn
   hersteld.
4. scripts/taalcontrole.py heeft een achtste controle: tekst die Nederlands
   bleef terwijl er een vertaling voor bestaat. Die kijkt naar alle brontalen
   tegelijk en had dit gevonden.

Geen enkel adres verandert, er komen geen kapotte links bij en de Nederlandse
pagina's blijven gelijk.

Co-Authored-By: Claude Opus 5 <noreply@anthropic.com>
MSGEOF

git push
echo
echo "Klaar. Patch 89 staat op main."
